@bswartz let me know what do you think about the new change. CSI plugin developers have to consider this change and introduce additional code, e.g.:

```golang
import (
  ...
        "k8s.io/apimachinery/pkg/api/resource"
        "k8s.io/kubernetes/pkg/volume"
)

...

func (ns *nodeServer) NodeExpandVolume(ctx context.Context, req *csi.NodeExpandVolumeRequest) (*csi.NodeExpandVolumeResponse, error) {
...
        r := resizefs.NewResizeFs(ns.Mount.GetBaseMounter())
        newSize := resource.NewQuantity(req.GetCapacityRange().GetRequiredBytes(), resource.BinarySI).ToDec()
        resizeOpts := volume.NodeResizeOptions{
                DevicePath:      devicePath,
                DeviceMountPath: volumePath,
                NewSize:         *newSize,
        }
        if _, err := r.Resize(resizeOpts, true); err != nil {
                return nil, status.Errorf(codes.Internal, "Could not resize volume %q: %v", volumeID, err)
        }
        return &csi.NodeExpandVolumeResponse{}, nil
}
